-- Phase 6 world hierarchy schema; existing Phase 3/4/5 tables remain unchanged.
create table if not exists countries (country_id text primary key, name text not null, capital_province_id text not null, population bigint not null check(population>=0), government_type text not null, stability integer not null check(stability between 0 and 100), treasury bigint not null check(treasury>=0), national_power integer not null check(national_power>=0), color text not null);
create table if not exists provinces (province_id text primary key, country_id text not null, name text not null, population bigint not null check(population>=0));
create table if not exists districts (district_id text primary key, province_id text not null references provinces(province_id), name text not null, population bigint not null check(population>=0), importance integer not null check(importance>=0));
create table if not exists cities (city_id text primary key, district_id text not null references districts(district_id), name text not null, population bigint not null check(population>=0));
create table if not exists population (province_id text primary key references provinces(province_id), workers bigint not null check(workers>=0), soldiers bigint not null check(soldiers>=0), tax_base integer not null, growth_rate numeric not null);
create table if not exists province_development (province_id text primary key references provinces(province_id), development_level integer not null, urbanization integer not null, industry integer not null, agriculture integer not null, infrastructure integer not null);
create table if not exists resources_map (province_id text primary key references provinces(province_id), oil_reserve integer not null, iron integer not null, agriculture integer not null, energy integer not null);
